import 'package:share_plus/share_plus.dart';

Future<void> shareDraft(BuildContext context, String text, List<XFile> files) async {
  final box = context.findRenderObject() as RenderBox?;
  final result = await SharePlus.instance.share(
    ShareParams(
      text: text,
      subject: 'NEFORUM post',
      files: files, // List<XFile>; combinable with text
      // Required on iPad/macOS so the popover has an anchor (13.3.0 stopped throwing when missing)
      sharePositionOrigin: box == null ? null : box.localToGlobal(Offset.zero) & box.size,
    ),
  );
  switch (result.status) {
    case ShareResultStatus.success: /* result.raw = activity id on iOS */ break;
    case ShareResultStatus.dismissed: break;
    case ShareResultStatus.unavailable: break;
  }
}

