      android: AndroidNotificationDetails('posts', 'Scheduled posts',
          actions: [AndroidNotificationAction('post_now', 'Post now')]),
      iOS: DarwinNotificationDetails(categoryIdentifier: 'neforum_post'),
    ),
    androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,
    payload: payload,
  );
}
