import 'package:workmanager/workmanager.dart';

// Must be top-level; on macOS it must be literally named callbackDispatcher in the main library.
@pragma('vm:entry-point')
void callbackDispatcher() {
  Workmanager().executeTask((task, inputData) async {
    switch (task) {
      case 'neforum.flush_queue':        // Android unique task name / iOS BGTask identifier
      case Workmanager.iOSBackgroundTask: // legacy background-fetch entry
        await flushPostQueue(inputData);
    }
    return true; // false = failure (retry per backoffPolicy)
  }, onTaskStopped: (task, reason) async {});
}

void main() {
  Workmanager().initialize(callbackDispatcher);
  runApp(const App());
}

Future<void> scheduleFlush() async {
  await Workmanager().registerPeriodicTask(
    'neforum-flush', 'neforum.flush_queue',
    frequency: const Duration(minutes: 15), // 15 min minimum on Android AND iOS
    constraints: Constraints(networkType: NetworkType.connected),
    existingWorkPolicy: ExistingPeriodicWorkPolicy.keep,
    inputData: {'mode': 'queue'}, // native Map transfer since 0.8.0 (no JSON)
  );
  await Workmanager().registerOneOffTask(
    'neforum-post-123', 'neforum.flush_queue',
    initialDelay: const Duration(minutes: 2),
    backoffPolicy: BackoffPolicy.exponential,
  );
  // iOS long-running: registerProcessingTask('neforum.flush_queue', 'neforum.flush_queue')
  // iOS Info.plist: UIBackgroundModes [fetch, processing]; BGTaskSchedulerPermittedIdentifiers [neforum.flush_queue]
  // iOS AppDelegate.swift: WorkmanagerPlugin.registerLaunchHandlers(); WorkmanagerPlugin.setPluginRegistrantCallback{...};
  //   WorkmanagerPlugin.registerPeriodicTask(withIdentifier: "neforum.flush_queue", frequency: NSNumber(value: 15*60))
  //   or WorkmanagerPlugin.registerBGProcessingTask(withIdentifier: "neforum.flush_queue")
}

