import 'package:flutter_web_auth_2/flutter_web_auth_2.dart';
import 'dart:io' show Platform;

Future<Uri> runAuth(Uri authorizeUrl) async {
  final desktop = Platform.isWindows || Platform.isLinux;
  // Mobile/macOS: custom scheme 'neforum' (RFC 3986: lowercase letters, digits, + - . ; no underscores).
  // Windows/Linux with useWebview:false: scheme MUST be 'http://localhost:PORT' (or http://127.0.0.1:PORT);
  // the plugin binds HttpServer on 127.0.0.1:PORT, serves landingPageHtml and returns req.requestedUri.
  final callback = desktop ? 'http://localhost:43823' : 'neforum';
  final result = await FlutterWebAuth2.authenticate(
    url: authorizeUrl.toString(),
    callbackUrlScheme: callback,
    options: const FlutterWebAuth2Options(
      useWebview: false,      // desktop: open system browser instead of desktop_webview_window
      preferEphemeral: false, // iOS/macOS ASWebAuthenticationSession ephemeral session
      timeout: 5 * 60,
    ),
  );
  return Uri.parse(result); // e.g. neforum://callback?code=...&state=...
}
